import{_ as t,C as r,o as i,c as o,a8 as n,E as s}from"./chunks/framework.NQDCei_r.js";const w=JSON.parse('{"title":"EOPF Explorer Webinar #3: Updates on EOPF Zarr & Cloud-Native S1/S2 Data Fusion","description":"","frontmatter":{"title":"EOPF Explorer Webinar #3: Updates on EOPF Zarr & Cloud-Native S1/S2 Data Fusion","layout":"page"},"headers":[{"level":3,"title":"What You Will Learn","slug":"what-you-will-learn","link":"#what-you-will-learn","children":[]},{"level":3,"title":"Why It Matters","slug":"why-it-matters","link":"#why-it-matters","children":[]},{"level":3,"title":"Be Part of the Change","slug":"be-part-of-the-change","link":"#be-part-of-the-change","children":[]},{"level":3,"title":"Who Should Attend","slug":"who-should-attend","link":"#who-should-attend","children":[]},{"level":3,"title":"Learn More","slug":"learn-more","link":"#learn-more","children":[]}],"relativePath":"webinars-events/webinar-3-data-fusion.md","filePath":"webinars-events/webinar-3-data-fusion.md"}'),l={name:"webinars-events/webinar-3-data-fusion.md"};function h(d,e,p,u,c,f){const a=r("CTASection");return i(),o("div",null,[e[0]||(e[0]=n('<h1 id="eopf-explorer-webinar-3-updates-on-eopf-zarr-cloud-native-s1-s2-data-fusion" tabindex="-1">EOPF Explorer Webinar #3: Updates on EOPF Zarr &amp; Cloud-Native S1/S2 Data Fusion <a class="header-anchor link" href="#eopf-explorer-webinar-3-updates-on-eopf-zarr-cloud-native-s1-s2-data-fusion" aria-label="Permalink to &quot;EOPF Explorer Webinar #3: Updates on EOPF Zarr &amp; Cloud-Native S1/S2 Data Fusion&quot;">​</a></h1><div class="padding round margin-bottom row"><div class="max"><div>November 25, 2026 | 15:00-16:00 CET</div></div><a href="https://buytickets.at/thrivegeo/2495266" target="_blank" class="button primary">Register Now</a></div><p>Join ESA, Development Seed, EOX and thriveGEO for the third EOPF Explorer webinar. We move beyond visualisation to show what EOPF Zarr can do for serious multi-mission analysis, and compare its performance against other data formats.</p><h3 id="what-you-will-learn" tabindex="-1">What You Will Learn <a class="header-anchor link" href="#what-you-will-learn" aria-label="Permalink to &quot;What You Will Learn&quot;">​</a></h3><p>Many applications need data from more than one Sentinel mission, but combining Sentinel-1 radar with Sentinel-2 optical imagery still requires stitching together separate access paths and processing stacks. In this webinar, you will see data fusion scenarios that bring Sentinel-1 and Sentinel-2 together with titiler-openeo, packaged as reusable process graphs that you can adapt to your own area and question.</p><p>We will also put EOPF Zarr under the microscope. We will share benchmark results showing how the format performs in practice, and how design choices such as chunking and multiscale pyramids affect access and rendering speed. By the end, you will know how the EOPF Zarr format compares to traditional data formats.</p><h3 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor link" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h3><p>GeoZarr is the official format for EOPF Zarr, and it is the planned future distribution format for Copernicus Sentinel data. A format is only as useful as the work it enables. The fusion scenarios show that EOPF Zarr supports analysis through a standard processing API, not just viewing. The benchmarks give you evidence to plan your own transition with confidence.</p><p>Everything is built with open-source technology, including TiTiler, openEO, GDAL, OpenLayers and STAC, so what you see can be reused, adapted and improved by the community.</p><h3 id="be-part-of-the-change" tabindex="-1">Be Part of the Change <a class="header-anchor link" href="#be-part-of-the-change" aria-label="Permalink to &quot;Be Part of the Change&quot;">​</a></h3><p>The EOPF Explorer is a community-driven project, and your voice shapes how Sentinel data will be accessed in the future. With growing adoption and ecosystem support, this is your opportunity to engage during development. This webinar is a continuation of a capacity-building series started at the beginning of 2026. Join us to try the next step with us, and tell us which fusion workflows and performance questions matter most to you. There will be plenty of time for questions and discussion.</p><h3 id="who-should-attend" tabindex="-1">Who Should Attend <a class="header-anchor link" href="#who-should-attend" aria-label="Permalink to &quot;Who Should Attend&quot;">​</a></h3><ul><li>Earth observation data users and researchers</li><li>Data scientists interested in cloud-native workflows</li><li>Web developers creating geospatial applications</li><li>Anyone planning their transition to EOPF Zarr who wants to know how it performs</li></ul><h3 id="learn-more" tabindex="-1">Learn More <a class="header-anchor link" href="#learn-more" aria-label="Permalink to &quot;Learn More&quot;">​</a></h3><ul><li>Software and services: <a href="/pr-preview/pr-128/software-services/index" class="link">https://explorer.eopf.copernicus.eu/software-services</a></li><li>Data model: <a href="/pr-preview/pr-128/software-services/datamodel/index" class="link">https://explorer.eopf.copernicus.eu/software-services/datamodel/</a></li><li>Project site: <a href="/pr-preview/pr-128/" class="link">https://explorer.eopf.copernicus.eu/</a></li></ul>',15)),s(a,{style:{"margin-bottom":"0px"},title:"Join the discussion!",tagline:"We welcome your feedback and contributions.",primaryButton:"Visit the EOPF Forum",primaryLink:"https://discourse.eopf.copernicus.eu/c/eopf-explorer/17",dark:""})])}const b=t(l,[["render",h]]);export{w as __pageData,b as default};
